def shell(title,body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · HEMS evidence library</title><link rel="stylesheet" href="style.css?v=4"><link rel="stylesheet" href="design.css?v=4"><link rel="stylesheet" href="theme.css?v=4"><link rel="stylesheet" href="figures.css?v=4"></head><body data-lang="en"><nav><div><b>HEMS / Evidence library</b><a href="index.html">{pair('All articles','همه مقالات')}</a><a href="../PROJECT_BACKLOG.html">{pair('Project backlog','فهرست کارها')}</a><select id="language" aria-label="Report language"><option value="en">English</option><option value="both">English + فارسی</option><option value="fa">فارسی</option></select><button onclick="window.print()">{pair('Print','چاپ')}</button></div></nav><main>{body}<footer>{pair('Local research library · Source evidence and critical commentary are labeled separately. Review status reflects actual coverage.','کتابخانه محلی پژوهش · شواهد مقاله و تحلیل انتقادی جداگانه مشخص شده‌اند. وضعیت مرور بر اساس پوشش واقعی است.')}</footer></main><script src="shared.js?v=4"></script><script src="experience.js?v=4"></script></body></html>'''

categories={
'Modeling & automation':'مدل‌سازی و خودکارسازی',
'Preferences, scheduling & planning':'ترجیحات، زمان‌بندی و برنامه‌ریزی',
'Causal & probabilistic diagnosis':'تشخیص علّی و احتمالاتی',
'Digital Twins & safety':'دوقلوی دیجیتال و ایمنی',
'Reviews & context':'مرورها و زمینه پژوهش',
'Simulation & benchmark':'شبیه‌سازی و معیار ارزیابی'}
cards=[]
for n,x in enumerate(inventory,1):
    title=esc(x['title']); cat=x['category'];ready=x['id'] in available_ids
    cards.append(f'''<article class="card" data-category="{esc(cat)}" data-search="{esc((x['title']+' '+x['doi']).lower())}"><div><span class="eyebrow">{n:02}</span> <span class="pill {'queued' if not ready else ''}">{pair('Report available' if ready else 'Queued for analysis','گزارش آماده' if ready else 'در صف تحلیل')}</span></div>{('<img class="cover" src="assets/la-upahem/figure-2.png" alt="LA-UPAHEM architecture">' if x['id']=='la-upahem' else '<img class="cover" src="assets/huang/figure-7.png" alt="EECL Bayesian network">' if x['id']=='article-02' else '')}<h3>{title}</h3><p class="muted">{pair(cat,categories[cat])}</p><small>{x['pages']} PDF pages · {len(x['copies'])} file(s)</small><a class="btn" href="{x['id']}.html">{pair('Read report' if ready else 'View source record','مطالعه گزارش' if ready else 'مشاهده مشخصات منبع')} →</a></article>''')
    if not ready:
        body=f'<div class="hero"><span class="eyebrow">SOURCE RECORD / QUEUED</span><h1>{title}</h1></div><div class="panel"><h2>{pair("Analysis pending","تحلیل در انتظار انجام")}</h2><p>{pair("This article has been inventoried. Its full methodology, figures, tables, results, and bibliography have not yet been reviewed. No summary is presented as a completed analysis.","این مقاله فهرست‌برداری شده است. روش‌شناسی، شکل‌ها، جدول‌ها، نتایج و کتاب‌نامه هنوز به‌طور کامل مرور نشده‌اند. این صفحه گزارش تحلیلی کامل نیست.")}</p><p>{pair(cat,categories[cat])} · {x["pages"]} pages</p><a href="{Path(x["path"]).as_uri()}">{pair("Open original PDF","بازکردن فایل اصلی")}</a><p>DOI: {esc(x["doi"] or "Not yet verified")}</p><details><summary>File provenance / منشأ فایل</summary><pre>{esc(json.dumps(x,ensure_ascii=False,indent=2))}</pre></details></div>'
        (OUT/(x['id']+'.html')).write_text(shell(x['title'],body),encoding='utf-8')
landing=f'''<div class="hero"><span class="eyebrow">P0 / ARTICLE-BY-ARTICLE EVIDENCE</span><h1>{pair('The research behind the implementation.','پژوهش‌هایی که مبنای پیاده‌سازی هستند.')}</h1><p class="sub">{pair('Explore the methods, experiments, figures, and limitations of the HEMS literature. Implementation references come first; every report keeps its evidence visible.','روش‌ها، آزمایش‌ها، شکل‌ها و محدودیت‌های منابع مدیریت انرژی خانه را بررسی کنید. منابع پیاده‌سازی در اولویت‌اند و شواهد هر گزارش قابل پیگیری است.')}</p></div><div class="stats"><div class="card"><b class="stat">{len(inventory)}</b>{pair('Unique articles','مقاله یکتا')}</div><div class="card"><b class="stat">{len(available_ids)}</b>{pair('Report available','گزارش آماده')}</div><div class="card"><b class="stat">{analysis_figure_count}</b>{pair('Original visual evidence views','نمای شواهد تصویری اصلی')}</div></div><div class="notice">{pair('Explore available reports with original figures, experimental comparisons, methods, full bibliographies, and project-role assessments. Report coverage is recorded per article; supplementary material absent from supplied files is identified explicitly. Order is an editorial implementation priority, not an author claim.','گزارش‌ها شامل شکل‌های اصلی، مقایسه‌ها، روش‌ها، کتاب‌نامه کامل و ارزیابی نقش در پروژه‌اند. پوشش هر مقاله مشخص شده و فایل‌های تکمیلی ارائه‌نشده صریحاً ذکر می‌شوند. ترتیب مطالعه اولویت تدوینی برای پیاده‌سازی است و ادعای نویسندگان نیست.')}</div><div class="toolbar"><input id="search" type="search" placeholder="Search title / DOI · جست‌وجو" aria-label="Search articles"><select id="category" aria-label="Category"><option value="all">All categories / همه دسته‌ها</option>{''.join(f'<option value="{esc(c)}">{esc(c)} / {f}</option>' for c,f in categories.items())}</select></div><p id="count" role="status"></p><div class="grid">{''.join(cards)}</div>'''
landing+='''<script>document.addEventListener('DOMContentLoaded',()=>{const input=document.getElementById('search'),category=document.getElementById('category');function filter(){let n=0;document.querySelectorAll('[data-search]').forEach(el=>{el.hidden=!(el.dataset.search.includes(input.value.toLowerCase())&&(category.value==='all'||category.value===el.dataset.category));el.style.display=el.hidden?'none':'';if(!el.hidden)n++});document.getElementById('count').textContent=n+' articles / مقاله'}input.oninput=filter;category.onchange=filter;filter()});</script>'''
(OUT/'index.html').write_text(shell('Research literature',landing),encoding='utf-8')

sections=[]
def section(id,en,fa,body): sections.append((id,en,fa,f'<section id="{id}" class="panel"><h2>{pair(en,fa)}</h2>{body}</section>'))
section('scope','Paper identity & coverage','مشخصات و پوشش مقاله',para('Xiao Du, Fengji Luo, Juntao Hu, Wei Zhou, Junhao Wen. Applied Energy 415 (2026), 127976. Available online 24 April 2026. DOI: 10.1016/j.apenergy.2026.127976.','شیائو دو و همکاران؛ Applied Energy، جلد ۴۱۵، سال ۲۰۲۶، شماره 127976. انتشار آنلاین: ۲۴ آوریل ۲۰۲۶.',1)+para('Coverage: main text and appendices A–E; all 9 figures; source views for all 14 tables; full source-page viewer and bibliography. Summaries are selective; original pages retain exact equations, prompts, code, and complete numerical tables. Figures are reproduced locally for this research report.','پوشش: متن اصلی و پیوست‌های A تا E، هر ۹ شکل، منبع هر ۱۴ جدول، نمایش تمام صفحات و کتاب‌نامه. خلاصه‌ها گزینشی‌اند؛ معادلات، پرامپت‌ها، کد و داده‌های کامل جدول‌ها در صفحات اصلی حفظ شده‌اند.',19))
section('questions','Problem, questions & hypotheses','مسئله، پرسش‌ها و فرضیه‌ها',para('The stated problem is translating evolving natural-language preferences into executable DRL objectives without manual reward engineering. The paper motivates static rewards/states and slow, history-based adaptation as gaps.','مسئله بیان‌شده، تبدیل ترجیحات متغیر زبان طبیعی به اهداف اجرایی یادگیری تقویتی بدون مهندسی دستی پاداش است. پاداش و حالت ثابت و انطباق کند مبتنی بر سابقه از شکاف‌های مطرح‌شده‌اند.',2)+para('No numbered hypothesis set is explicitly stated. Section 6 organizes the evaluation around preference alignment, iterative mechanism/agent contributions, robustness, and generality. Section 6.5 explicitly asks whether iterative refinement justifies its complexity.','مجموعه فرضیه شماره‌گذاری‌شده صریح ارائه نشده است. ارزیابی بخش ۶ بر هم‌راستایی با ترجیحات، نقش تکرار و عامل‌ها، استحکام و تعمیم متمرکز است. بخش ۶٫۵ می‌پرسد آیا بهبود تکراری پیچیدگی خود را توجیه می‌کند.',11))
section('method','Method & implementation details','روش و جزئیات پیاده‌سازی',para('The preference-driven MDP generates a coordinated pair: state modifier Mₚ and reward Rₚ. The physical scenario controls AC and BESS; PV and the grid supply energy, while other appliances form uncontrollable baseline load. Eqs. (1)–(4) define objectives and the preference mapping; Eqs. (5)–(10) define physical/stochastic models.','در MDP مبتنی بر ترجیحات، اصلاح‌گر حالت Mₚ و پاداش Rₚ به‌صورت هماهنگ تولید می‌شوند. کنترل شامل تهویه و باتری است؛ پنل خورشیدی و شبکه انرژی را تأمین می‌کنند و سایر وسایل بار پایه‌اند. معادلات ۱ تا ۴ اهداف و نگاشت ترجیح و معادلات ۵ تا ۱۰ مدل‌های فیزیکی و تصادفی را تعریف می‌کنند.',3)+para('Code Generation creates n candidate reward/state pairs. Result Analysis inspects KPIs and trajectories and supplies corrective feedback. Optimal Performance Search selects the next warm-start and final policy. Memory retrieval uses the latest m=3 iterations; trajectories are withheld from Code Generation and supplied to Result Analysis. Algorithm 1 describes the nested loop.','عامل تولید کد n جفت پاداش/حالت می‌سازد؛ عامل تحلیل، شاخص‌ها و مسیرها را بررسی و بازخورد اصلاحی می‌دهد؛ عامل جست‌وجوی عملکرد، شروع گرم و سیاست نهایی را انتخاب می‌کند. حافظه سه تکرار اخیر را بازیابی می‌کند؛ مسیرها برای تحلیل نتایج ارسال می‌شوند و از ورودی تولید کد حذف می‌شوند. الگوریتم ۱ حلقه تودرتو را شرح می‌دهد.',7)+para('SAC uses actor–critic MLP dimensions [256,512,64,512,256], ReLU, Adam 3×10⁻⁴, discount 0.99, Polyak 0.005, automatic entropy tuning, batch 256, replay capacity 10⁶. DeepSeek V3 (671B) uses temperature 0.7 for generation and 0 for evaluation parsing. Platform: Ubuntu 20.04, Python 3.10, PyTorch 2.0, i7-14600K, RTX 4090.','شبکه‌های SAC دارای ابعاد [256,512,64,512,256] با ReLU، Adam با نرخ 3×10⁻⁴، تنزیل ۰٫۹۹، ضریب Polyak برابر ۰٫۰۰۵، تنظیم خودکار آنتروپی، دسته ۲۵۶ و حافظه 10⁶ هستند. دمای DeepSeek V3 برای تولید ۰٫۷ و برای ارزیابی صفر است. بستر اجرا Ubuntu 20.04، Python 3.10، PyTorch 2.0 و RTX 4090 گزارش شده است.',8)+para('Appendices C–D provide prompts and reference code. Appendix E requires BaseReward/BaseStateModifier interfaces, two Python code blocks, module/class checks, five random-action runtime tests, up to 50 generation attempts per sample, and documentation of 33 observation features. These are reported code-validation measures.','پیوست‌های C و D پرامپت و کد مرجع را ارائه می‌کنند. پیوست E شامل رابط کلاس‌ها، دو بلوک کد، بررسی ماژول و کلاس، پنج گام تصادفی آزمون اجرا، حداکثر ۵۰ تلاش تولید برای هر نمونه و مستندسازی ۳۳ ویژگی مشاهده است. این موارد اقدامات اعتبارسنجی کد گزارش‌شده‌اند.',19))
section('experiments','Experiments, data & evaluation','آزمایش‌ها، داده‌ها و ارزیابی',para('Training, validation, and test days are disjoint random subsets. Outer-loop feedback uses validation episodes; test days are withheld. Results average 10 independent seeds per preference. Each one-day episode has 288 five-minute steps; default search uses 5 iterations × 5 candidates × 90 training episodes.','روزهای آموزش، اعتبارسنجی و آزمون به زیرمجموعه‌های تصادفی مجزا تقسیم شده‌اند. بازخورد حلقه بیرونی از اعتبارسنجی می‌آید و آزمون کنار گذاشته می‌شود. نتایج میانگین ۱۰ بذر مستقل برای هر ترجیح‌اند. هر روز ۲۸۸ گام پنج‌دقیقه‌ای و تنظیم پیش‌فرض ۵ تکرار، ۵ نامزد و ۹۰ اپیزود آموزش دارد.',8)+para('Eight preferences: P1 cost, P2 emissions, P3 comfort; P4 no battery charging while home; P5 AC only when home at night; P6 discharge only at peak tariff; P7 conditional AC suppression with cost-saving preference; P8 no particular preference.','هشت ترجیح: هزینه، انتشار، آسایش؛ منع شارژ باتری هنگام حضور؛ تهویه فقط هنگام حضور در شب؛ تخلیه فقط در تعرفه اوج؛ مهار شرطی تهویه همراه صرفه‌جویی؛ و حالت بدون ترجیح ویژه.',4)+para('Data: Pecan Street apartment #3938, San Diego, 2016, 120 summer days; NOAA Trinidad Head weather; CityLearn v2 tariff and carbon profiles; stochastic occupancy. Table 13 reports five-minute downsampling and weather missingness of 0.32% solar / 5.72% temperature, filled backward then forward.','داده‌ها شامل آپارتمان 3938 از Pecan Street در سن‌دیگو، ۱۲۰ روز تابستان ۲۰۱۶، آب‌وهوای Trinidad Head، تعرفه و شدت کربن CityLearn v2 و حضور تصادفی است. جدول ۱۳ تجمیع به پنج دقیقه و داده گمشده خورشید ۰٫۳۲٪ و دما ۵٫۷۲٪ با پرکردن پس‌رو سپس پیش‌رو را گزارش می‌کند.',16)+para('WIR is the weighted relative KPI improvement against fixed D1 reference KPIs (Eq. 18); it is reported for macro preferences. RCR measures compliance with micro-rule predicates (Eq. 19). The evaluation parser produces canonical weights/rules at temperature 0. Failure rate counts runs with invalid policies, device violations, degenerate behavior, or divergence.','WIR بهبود نسبی وزن‌دار شاخص‌ها نسبت به مرجع ثابت D1 است و برای ترجیحات کلان گزارش می‌شود. RCR رعایت گزاره‌های قواعد خرد را می‌سنجد. پارسر ارزیابی وزن‌ها و قواعد معیار را با دمای صفر تولید می‌کند. نرخ شکست شامل سیاست نامعتبر، نقض قیود تجهیز، رفتار منحط یا واگرایی است.',9))
baseline=[('D1','Fixed-reward DRL','یادگیری تقویتی با پاداش ثابت'),('D2','Oracle macro weights','وزن‌های کلان اوراکل'),('D3','Oracle weights + handcrafted micro-rule penalties','وزن‌های اوراکل و جریمه قواعد خرد دستی'),('H1','One-shot static preference parsing','تفسیر یک‌مرحله‌ای ترجیحات'),('H2','LLM reward generation each training episode; no dedicated analysis agent [31]','تولید پاداش در هر اپیزود، بدون عامل تحلیل مستقل [31]'),('H3','Per-timestep LLM action filtering of the D1 policy [29]','فیلتر کنش سیاست D1 در هر گام با مدل زبانی [29]')]
section('baselines','Compared baselines & ablations','خط‌مبناها و حذف مؤلفه‌ها','<div class="scroll"><table><tr><th>ID</th><th>'+pair('Definition','تعریف')+'</th></tr>'+''.join(f'<tr><td>{a}</td><td>{pair(b,c)}</td></tr>' for a,b,c in baseline)+'</table></div>'+cite(8,'§6.2 / Table 3')+para('Ablations remove Result Analysis feedback or Optimal Performance Search warm-start. Candidate count is varied from 1 to 9; backend algorithms include SAC, TD3, PPO, DDPG, MASAC, and MADDPG. Language/model tests include English, Chinese, Spanish and DeepSeek V3, GPT-4, Claude Sonnet 4.0, LLaMA-3 70B/8B.','در حذف مؤلفه، بازخورد تحلیل یا شروع گرم جست‌وجوی عملکرد حذف می‌شود. شمار نامزدها از ۱ تا ۹ تغییر می‌کند؛ الگوریتم‌های SAC، TD3، PPO، DDPG، MASAC و MADDPG و سه زبان انگلیسی، چینی و اسپانیایی با چند مدل زبانی آزموده شده‌اند.',15))
section('results','Reported results','نتایج گزارش‌شده',para('Main aggregate: WIR 0.13, RCR 0.84; failure rate 5.4% versus static parsing 34.3%. Feedback removal gives 16.3% failure and warm-start removal 8.1%. These are paper-reported simulation results, not independently reproduced measurements.','نتیجه تجمیعی اصلی: WIR برابر ۰٫۱۳، RCR برابر ۰٫۸۴ و شکست ۵٫۴٪ در برابر ۳۴٫۳٪ تفسیر ایستا. حذف بازخورد شکست را به ۱۶٫۳٪ و حذف شروع گرم به ۸٫۱٪ می‌رساند. این‌ها نتایج شبیه‌سازی گزارش‌شده مقاله‌اند و مستقل بازتولید نشده‌اند.',13)+para('Table 6: LA-UPAHEM trains 2250 episodes, makes 15 LLM calls, consumes 57.30K tokens, and makes zero deployment-time LLM calls. H1 uses 2.15K tokens; H2 296.10K; H3 5486.40K over the stated 15-day cycle. Authors report a complete adaptation cycle of approximately 2.5–3.5 hours on their platform.','جدول ۶: روش پیشنهادی ۲۲۵۰ اپیزود، ۱۵ فراخوانی مدل و 57.30K توکن دارد و هنگام استقرار مدل زبانی را فراخوانی نمی‌کند. H1 برابر 2.15K، H2 برابر 296.10K و H3 برابر 5486.40K توکن در چرخه ۱۵روزه گزارش‌شده مصرف می‌کنند. زمان انطباق کامل حدود ۲٫۵ تا ۳٫۵ ساعت است.',13)+para('Robustness tests add Gaussian exogenous noise β={0,.05,.10,.15}, perturb dominant evaluation weights ±20%, and test paraphrases. The paper reports retained top ranking across nine preference/weight combinations. Under P3, discomfort spans 1.57–2.01 across tested noise levels.','آزمون استحکام شامل نویز گاوسی با β برابر صفر، ۰٫۰۵، ۰٫۱۰ و ۰٫۱۵، تغییر ۲۰٪ وزن غالب و بازنویسی ترجیحات است. مقاله حفظ رتبه نخست در نه ترکیب ترجیح/وزن و دامنه ناراحتی ۱٫۵۷ تا ۲٫۰۱ برای P3 را گزارش می‌کند.',13))

figs=[
(1,3,'System architecture of the considered HEMS scenario.','معماری سامانه مدیریت انرژی مورد مطالعه.','Energy flows connect PV/grid to BESS, AC, and baseline loads; information links connect user preferences, AMI/controller, database, and policy. No quantitative experimental series is encoded.','جریان انرژی میان خورشید/شبکه، باتری، تهویه و بار پایه و جریان اطلاعات میان کاربر، کنترل‌گر، پایگاه داده و سیاست نمایش داده شده است. این شکل سری داده آزمایشی عددی ندارد.'),
(2,6,'Overall architecture of the proposed LA-UPAHEM framework.','معماری کلی چارچوب LA-UPAHEM.','The diagram separates offline candidate generation, inner DRL training/evaluation, analysis, memory, and warm-start selection from deployed policy execution. n and iteration count are symbolic here; defaults are specified in §6.1.','شکل تولید نامزد، آموزش/ارزیابی، تحلیل، حافظه و شروع گرم آفلاین را از اجرای سیاست جدا می‌کند. شمار نامزد و تکرار در این نمودار نمادین‌اند و مقدار پیش‌فرض در بخش ۶٫۱ آمده است.'),
(3,10,'Weighted Improvement Ratio (WIR) under macro-level preferences P1:3, derived from Table 5. Higher WIR indicates better preference alignment relative to D1 (whose WIR = 0 by definition). Error bars show the standard deviation across random seeds.','WIR در ترجیحات کلان P1 تا P3 نسبت به D1؛ میله خطا انحراف معیار بذرهاست.','Printed bar labels, ordered P1/P2/P3: D1 0/0/0; D2/D3 −.03/.11/.14; H1 −.11/.06/.02; H2 −.06/.12/.08; H3 −.06/.02/.04; Ours .04/.15/.20. Error-bar magnitudes are not numerically labeled; none are estimated.','برچسب‌های چاپ‌شده به ترتیب P1/P2/P3: روش پیشنهادی ۰٫۰۴/۰٫۱۵/۰٫۲۰ است؛ مقادیر همه روش‌ها در متن انگلیسی آمده‌اند. اندازه میله‌های خطا برآورد نشده است.'),
(4,10,'Rule compliance rate (RCR) under behavioral rule preferences P4:7. Higher RCR indicates fewer rule violations. Error bars indicate standard deviation across random seeds.','نرخ رعایت قواعد P4 تا P7؛ مقدار بالاتر بهتر و میله خطا انحراف معیار است.','Printed labels P4/P5/P6/P7: D1 .41/.47/.43/.39; D2 .46/.52/.48/.43; D3 .73/.72/.71/.69; H1 .61/.65/.60/.59; H2 .64/.67/.63/.61; H3 .79/.82/.78/.77; Ours .84/.86/.83/.81. Error magnitudes are not estimated.','برچسب‌های چاپ‌شده روش پیشنهادی به ترتیب P4 تا P7 برابر ۰٫۸۴، ۰٫۸۶، ۰٫۸۳ و ۰٫۸۱ است. سایر روش‌ها در متن انگلیسی ثبت شده‌اند. مقدار خطا از نمودار تخمین زده نشده است.'),
(5,10,'Control trajectories of AC and BESS under micro-level preferences P4–6, compositional P7, and baseline P8.','مسیر کنترل تهویه و باتری برای ترجیحات خرد، ترکیبی و پایه.','Panels display indoor/outdoor temperature, AC power, and BESS power over two daily cycles, with occupancy and high-price overlays. Curves have no printed sample values; no trajectories are digitized. §6.4 explains preference-dependent suppression of charging and AC operation.','دما، توان تهویه و باتری در دو چرخه روزانه همراه حضور و زمان قیمت بالا نشان داده شده‌اند. نمونه‌های منحنی برچسب عددی ندارند؛ بنابراین داده‌برداری تخمینی انجام نشده است. بخش ۶٫۴ رفتار وابسته به ترجیحات را توضیح می‌دهد.'),
(6,12,'Radar plots of normalized KPI scores under each preference; each axis uses one minus min–max-normalized KPI across all method–preference pairs. Higher is better.','نمودار راداری امتیاز شاخص‌ها پس از نرمال‌سازی کمینه–بیشینه؛ بیشتر بهتر است.','Seven method panels compare cost, comfort, and emissions for P1–P8. Individual vertex values are not printed; source numerical KPIs are in Table 5. No vertex values are inferred.','هفت پنل هزینه، آسایش و انتشار را برای هشت ترجیح مقایسه می‌کنند. رأس‌ها عدد چاپ‌شده ندارند؛ داده اصلی در جدول ۵ است و از تصویر تخمین زده نشده است.'),
(7,12,'Convergence of preference alignment during training. Upper curves show the iteration-best policy; shaded regions indicate 95% confidence intervals across seeds. Lower panels show mean WIR/RCR per iteration.','همگرایی هم‌راستایی؛ سایه‌ها فاصله اطمینان ۹۵٪ و پنل‌های پایین میانگین هر تکرارند.','Left: WIR for P1; right: RCR for P5, comparing full method, no warm-start, and static H1 over five iterations. No exact curve samples or confidence interval endpoints are printed. Authors describe diminishing returns after early iterations in §6.5.','چپ WIR برای P1 و راست RCR برای P5 است. روش کامل، حذف شروع گرم و H1 در پنج تکرار مقایسه شده‌اند. نمونه دقیق منحنی یا دو سر فاصله اطمینان چاپ نشده و تخمین زده نشده است.'),
(8,13,'Module-wise ablation. Bars show average WIR (P1–3) and RCR (P4–7); error bars show across-seed standard deviation. Line reports failure rate.','حذف مؤلفه: WIR و RCR میانگین و نرخ شکست.','Printed labels (WIR/RCR/failure): no feedback .06/.65/16.3%; no warm-start .04/.68/8.1%; static H1 −.01/.61/34.3%; full .13/.84/5.4%.','برچسب‌های چاپ‌شده WIR/RCR/شکست: بدون بازخورد ۰٫۰۶/۰٫۶۵/۱۶٫۳٪؛ بدون شروع گرم ۰٫۰۴/۰٫۶۸/۸٫۱٪؛ H1 برابر ‎−۰٫۰۱/۰٫۶۱/۳۴٫۳٪؛ کامل ۰٫۱۳/۰٫۸۴/۵٫۴٪.'),
(9,13,'Effect of candidate count n on preference compliance (five iterations). Bars show WIR and RCR; line reports failure rate.','اثر شمار نامزدها با پنج تکرار بر هم‌راستایی و شکست.','Printed labels n=1/3/5/7/9: WIR .04/.09/.13/.13/.13; RCR .58/.76/.84/.85/.87; failure 18.3/8.5/5.4/5.1/4.7%. Additional candidates increase compute; authors describe gains beyond n=5 as negligible.','برای n برابر ۱/۳/۵/۷/۹: WIR برابر ۰٫۰۴/۰٫۰۹/۰٫۱۳/۰٫۱۳/۰٫۱۳؛ RCR برابر ۰٫۵۸/۰٫۷۶/۰٫۸۴/۰٫۸۵/۰٫۸۷؛ شکست ۱۸٫۳/۸٫۵/۵٫۴/۵٫۱/۴٫۷٪ است. نویسندگان سود بعد از پنج نامزد را ناچیز توصیف می‌کنند.')]
section('figures','All figures & extracted evidence','همه شکل‌ها و شواهد استخراج‌شده','<div class="notice">'+pair('Original figure crops below retain plotted labels. English captions reproduce or closely summarize the original; Persian captions are translations. Only printed numbers are transcribed. Click an image to inspect it at full size.','تصاویر اصلی، برچسب‌های نمودار را حفظ می‌کنند. عنوان انگلیسی بازنویسی نزدیک یا نقل عنوان و عنوان فارسی ترجمه است. فقط اعداد چاپ‌شده ثبت شده‌اند. برای بزرگ‌نمایی روی تصویر کلیک کنید.')+'</div>'+''.join(f'<figure id="fig-{n}"><h3>Fig. {n} / شکل {n}</h3><a href="assets/la-upahem/figure-{n}.png" target="_blank"><img loading="lazy" src="assets/la-upahem/figure-{n}.png" alt="Figure {n}: {esc(en)}"></a><figcaption>{pair(esc(en),fa)} {cite(p,"Figure "+str(n))}</figcaption>{para(esc(info),fa_info,p)}</figure>' for n,p,en,fa,info,fa_info in figs))
tables=[(1,3,'RL+LLM integration paradigms','الگوهای ادغام مدل زبانی و RL'),(2,4,'Eight preference categories','هشت ترجیح'),(3,8,'Baseline access and iteration comparison','دسترسی و تکرار خط‌مبناها'),(4,8,'Canonical weights and micro-rules','وزن‌ها و قواعد معیار'),(5,9,'Raw KPI mean ± standard deviation','میانگین و انحراف معیار شاخص‌ها'),(6,13,'Training and inference computational cost','هزینه محاسباتی آموزش و اجرا'),(7,14,'Gaussian noise robustness','استحکام در برابر نویز'),(8,14,'Evaluation weight sensitivity','حساسیت به وزن ارزیابی'),(9,14,'Preference paraphrase results','نتایج بازنویسی ترجیحات'),(10,15,'DRL algorithm compatibility','سازگاری الگوریتم‌های RL'),(11,15,'LLM and language comparisons','مقایسه مدل‌ها و زبان‌ها'),(12,16,'Household model parameters','پارامترهای مدل خانه'),(13,16,'Data provenance and preprocessing','منشأ و پیش‌پردازش داده'),(14,17,'Code-generation prompt structure','ساختار پرامپت تولید کد')]
section('tables','All tables & numerical source views','تمام جدول‌ها و منابع عددی','<p>'+pair('Every numbered table is indexed below. Open the source page for the complete original values, units, footnotes, and formatting; selected headline numbers appear above.','همه جدول‌های شماره‌دار در زیر فهرست شده‌اند. برای تمام مقادیر، واحدها و پانویس‌ها صفحه اصلی را باز کنید؛ اعداد کلیدی در بالا آمده‌اند.')+'</p>'+''.join(f'<details><summary>Table {n} · {pair(en,fa)}</summary><a href="assets/la-upahem/page-{p:02}.png" target="_blank"><img loading="lazy" style="width:100%" src="assets/la-upahem/page-{p:02}.png" alt="Original source page containing Table {n}"></a>{cite(p,"Table "+str(n))}</details>' for n,p,en,fa in tables))
section('limits','Author-stated strengths, limits & future work','نقاط قوت، محدودیت‌ها و آینده از دید نویسندگان',para('Authors emphasize offline LLM use, inspectable reward/state code, feedback plus warm-start synergy, and compatibility across algorithms/models/languages. They acknowledge privacy exposure through preferences, household context, and memory sent to APIs, and discuss minimization, retention limits, anonymization, and local LLMs.','نویسندگان کاربرد آفلاین مدل، کد قابل بازرسی، هم‌افزایی بازخورد و شروع گرم و سازگاری الگوریتمی و زبانی را برجسته می‌کنند. افشای ترجیحات، مشخصات خانه و حافظه در API نیز مطرح و کاهش داده، محدودیت نگهداری، ناشناس‌سازی و مدل محلی پیشنهاد می‌شود.',7)+para('The stated key limitation is episode-level adaptation requiring a new 2.5–3.5-hour cycle; abrupt intra-episode changes are outside scope. Future directions include policy libraries, online reward adaptation, multimodal preference cues, improved local small-model deployment, and community coordination. Data are available on request.','محدودیت اصلی، انطباق در سطح اپیزود با چرخه جدید ۲٫۵ تا ۳٫۵ساعته است؛ تغییر ناگهانی درون اپیزود خارج از دامنه است. کتابخانه سیاست، تطبیق آنلاین پاداش، ورودی چندوجهی، مدل محلی کوچک و هماهنگی محله از مسیرهای آینده‌اند. داده با درخواست قابل دریافت است.',15))
section('critical','Separately labeled critical analysis','تحلیل انتقادی با برچسب مستقل','<div class="notice critical">'+pair('The following are reviewer observations grounded in the cited passages, not findings or claims attributed to the authors.','موارد زیر ملاحظات مرورگر بر پایه شواهد ارجاع‌شده‌اند و نتیجه یا ادعای نویسندگان محسوب نمی‌شوند.')+'</div>'+para('Transfer to our benchmark requires an adapted implementation: this study uses AC/BESS, a thermodynamic model, five-minute timesteps, and CityLearn v2 tariff/carbon data; our selected setup uses different equipment and hourly LSTM dynamics. Published scores cannot be compared directly without matched experiments.','انتقال به معیار ما نیازمند پیاده‌سازی اقتباسی است: این مطالعه AC/BESS، مدل حرارتی و گام پنج‌دقیقه‌ای دارد، در حالی که محیط منتخب ما تجهیزات و دینامیک LSTM ساعتی متفاوت دارد. مقایسه مستقیم امتیازهای منتشرشده بدون آزمایش همسان مناسب نیست.',16)+para('Appendix E’s five-step runtime test and interface checks establish a limited code-validation procedure. They do not, by themselves, demonstrate a formal hard-safety guarantee over a complete episode. A separate safety specification is needed for our interventions.','آزمون پنج‌گامی و کنترل رابط در پیوست E رویه محدود اعتبارسنجی کد را نشان می‌دهند و به‌تنهایی تضمین رسمی ایمنی سخت در تمام اپیزود را اثبات نمی‌کنند. برای مداخلات پروژه ما مشخصات ایمنی مستقل لازم است.',19)+para('The temperature-zero evaluation parser is an operational target generator. Its output should not be interpreted as independently measured resident preference truth; the authors explicitly model an idealized user. Weight sensitivity experiments partially examine this dependence.','پارسر ارزیابی با دمای صفر، هدف عملیاتی تولید می‌کند. خروجی آن معادل حقیقت ترجیح اندازه‌گیری‌شده مستقل از ساکن نیست؛ نویسندگان آن را کاربر ایده‌آل می‌نامند. آزمون حساسیت وزن بخشی از این وابستگی را بررسی می‌کند.',8))

text=(ROOT/'reports/literature/la-upahem-full.txt').read_text(encoding='utf-8')
refs=text.split('\nReferences\n',1)[-1]
refs=re.sub(r'=== PDF PAGE \d+ ===','',refs)
refs=re.sub(r'^.*Downloaded from.*$|^X\. Du,.*$','',refs,flags=re.M)
matches=list(re.finditer(r'^\s*\[(\d+)\]\s+',refs,re.M))
bib=''
for j,m in enumerate(matches):
    content=refs[m.end():matches[j+1].start() if j+1<len(matches) else len(refs)]
    content=re.sub(r'\n\s*(19|20)\s*\n','\n',content)
    content=' '.join(content.split())
    if j==len(matches)-1: content=re.sub(r'\s+20\s*$','',content)
    bib+=f'<div class="reference" id="ref-{m[1]}"><b>[{m[1]}]</b> {esc(content)}</div>'
section('pages','Original pages & implementation appendices','صفحات اصلی و پیوست‌های پیاده‌سازی','<p>'+pair('Use the original pages to inspect equations, Table 5, code blocks, and full prompt text that PDF text extraction may omit. Appendix A/B: p.16; C: pp.16–18; D: p.18; E: pp.18–19.','برای معادلات، جدول ۵، کد و پرامپت‌هایی که استخراج متن ممکن است از قلم بیندازد، صفحات اصلی را ببینید. پیوست A/B صفحه ۱۶؛ C صفحات ۱۶ تا ۱۸؛ D صفحه ۱۸؛ E صفحات ۱۸ و ۱۹.')+'</p>'+''.join(f'<details><summary>PDF page {i} / صفحه {i}</summary><a href="assets/la-upahem/page-{i:02}.png" target="_blank"><img style="width:100%" loading="lazy" src="assets/la-upahem/page-{i:02}.png" alt="Original PDF page {i}"></a></details>' for i in range(1,21)))
section('references','References & source provenance','منابع و منشأ فایل','<p>Du et al. (2026). <a href="https://doi.org/10.1016/j.apenergy.2026.127976">https://doi.org/10.1016/j.apenergy.2026.127976</a> '+cite(1)+'</p><p>'+pair('The bibliography below is transcribed from this paper, not a claim that its cited works were independently read. Original bibliography pages 19–20 remain authoritative for typography and any extraction errors.','کتاب‌نامه زیر از همین مقاله استخراج شده و به معنی مطالعه مستقل منابع آن نیست. صفحات ۱۹ و ۲۰ برای نگارش اصلی و خطاهای احتمالی استخراج مرجع‌اند.')+'</p>'+bib+cite(19,'References')+cite(20,'References'))
sections=[(id,en,fa,''.join(part if part.startswith('<') else re.sub(r'\[(29|31)\]',r'<a href="#ref-\1">[\1]</a>',part) for part in re.split(r'(<[^>]+>)',body)) if id!='references' else body) for id,en,fa,body in sections]
toc=''.join(f'<a href="#{id}">{pair(en,fa)}</a>' for id,en,fa,_ in sections)
body='<div class="hero"><span class="eyebrow">01 / PREFERENCE ADAPTATION / SOURCE-BASED REPORT</span><h1>LA-UPAHEM</h1><p class="sub">'+pair('Adaptive home energy management to self-motivated user preferences via iterative LLM-augmented reinforcement learning','مدیریت تطبیقی انرژی خانه بر اساس ترجیحات خودانگیخته کاربر با یادگیری تقویتی تکراری تقویت‌شده با مدل زبانی')+'</p><span class="pill">'+pair('Report available · 9 figures · 14 tables · 20 pages','گزارش آماده · ۹ شکل · ۱۴ جدول · ۲۰ صفحه')+'</span></div><div class="layout"><aside class="toc">'+toc+'</aside><article class="report">'+''.join(s[3] for s in sections)+'</article></div>'
(OUT/'la-upahem.html').write_text(shell('LA-UPAHEM',body),encoding='utf-8')
print(f'Built {len(inventory)} article records; LA-UPAHEM report; {len(figs)} figures; {len(tables)} table views; {len(matches)} references')

